  if (typeof o.k !== "string" || !Array.isArray(o.v)) return null;
  return { k: o.k.slice(0, 24), v: o.v.slice(0, 8).map((n: unknown) => Math.max(1, Math.min(BOSS_PM_MAX, Math.floor(Number(n) || 1)))) };
