  e.mhp = safeRound(safeMul(e.mhp, m));
  e.hp = safeRound(safeMul(Math.max(1, e.hp), m));
  if ((e.mshd ?? 0) > 0) { e.mshd = safeRound(safeMul(e.mshd as number, m)); e.shd = safeRound(safeMul(e.shd ?? 0, m)); }
