    fill(ins, (dx, dy, r) => (r > 0.8 ? (dy < 0 ? L : D) : r > 0.55 ? (dx < 0 ? c : D) : r > 0.3 ? L : c));
    px(8, 9, W); px(9, 9, LL); px(8, 10, LL);
