  if (golden) { for (let i = 0; i < 8; i++) { const a = i * 0.7854 + 0.39; for (let r = 9; r <= 11; r++) px(Math.round(cx + Math.cos(a) * r), Math.round(cy + Math.sin(a) * r), r === 11 ? GL : G); } }
