  if ((p = efP(g, 74)) > 0 && adj && e.hp > 0 && R() < efc(0.12, p)) { efDmg(g, e, st.atk * 0.8, EFX[74].c); floatTxt(g, e.x, e.y - 0.8, "COUNTER", EFX[74].c); efSfx(g, 74); }
