  if ((p = efP(g, 83)) > 0 && adj && e.hp > 0 && okMinor(e) && R() < efc(0.2, p)) { pushEn(g, e, h.x, h.y, 2); burst(g, e.ax * TS + 12, e.ay * TS + 12, 8, [EFX[83].c, "#ffffff"], 70, 30); efSfx(g, 83); }
