  if (emberHp > 0 && petRareOf(g, PRT_EMBER)) {
    const soak = Math.min(emberHp, dmg);
    g.petEmberHp = emberHp - soak;
    dmg -= soak;
    if (soak > 0) floatTxt(g, g.hero.x + 0.3, g.hero.y - 0.2, "WARD " + soak, "#ffb040");
    if (dmg <= 0) return;
  }
