  const wx = k === "storm" ? 0.55 : k === "rain" ? 0.32 : k === "blizzard" ? 0.3 : k === "lightning" ? 0.22 : k === "snow" ? 0.18 : k === "drizzle" ? 0.16 : k === "drift" || k === "frost" ? 0.12 : 0;
