  if (!(m.t > 0)) { m.t = now; return; }
  const gap = now - m.t;
  if (gap < -MINE_ROLLBACK_TOL_SEC * 1000) { m.t = now; m.rb++; return; } // clock rollback guard
  if (gap < 0) return;
