  if (x >= MINE_CAVE.x && x < MINE_CAVE.x + MINE_CAVE.w && y >= MINE_CAVE.y && y < MINE_CAVE.y + MINE_CAVE.h) return "cave";
  if (x === MINE_RACK.x && y === MINE_RACK.y) return "rack";
  if (x === MINE_CHEST.x && y === MINE_CHEST.y) return "chest";
