  const h = g.hero, bx = -a.hx, by = -a.hy, lx = -a.hy, ly = a.hx;
  const back = 1.25 + (k >= 3 ? 1.15 : 0), lat = ((k % 3) - 1) * 1.2 + (k >= 3 ? 0.55 : 0);
