      const s = nkOf(g); if (!s.own[3]) s.own[3] = 1; s.got = true;
      if (!s.eq.includes(3)) { while (s.eq.length >= nkCap(g)) { const old = s.eq.shift(); if (old !== undefined) nkUnwear(g, old); } s.eq.push(3); }
