  let dodge = 0;
  eachActiveSockBonus(g.eq, (def, mag) => { if (def.kind === "mirrorward") dodge += 0.020 * mag; });
  if (dodge > 0 && R() < Math.min(0.12, dodge)) { floatTxt(g, g.hero.x, g.hero.y - 0.5, "MIRROR", "#80ffc0"); return 0; }
