    const before = it.sk ? JSON.stringify(it.sk.map((z: { c: number; g?: unknown }) => [z.c, !!z.g])) : "";
    ensurePrisSocketLayout(it);
    const after = it.sk ? JSON.stringify(it.sk.map((z: { c: number; g?: unknown }) => [z.c, !!z.g])) : "";
