  if (R() < wch) e.elW = ELS[ri(ELS.length)];
  const nR = bossy ? (R() < 0.7 ? 1 + (R() < 0.35 ? 1 : 0) : 0) : lesser ? (R() < 0.10 ? 1 : 0) : e.cls === 1 ? (R() < 0.35 ? 1 : 0) : e.rare ? (R() < 0.4 ? 1 : 0) : (R() < 0.12 ? 1 : 0);
