    O6_LOG.capped++; O6_LOG.wasted += dmg - ok;
    if ((e.o6rt ?? -9) + 0.5 <= now) { e.o6rt = now; floatTxt(g, e.x + 0.3, e.y - 0.6, "RESIST", "#c0a0ff"); }
