  const q = [[x, y]];
  const stairs: number[][] = [];
  if (hx !== undefined) { for (let k = 0; k < MW * MH; k++) if (g.map[k] === 2) stairs.push([k % MW, (k / MW) | 0]); }
  const bad = (nx: number, ny: number) => hx !== undefined && (Math.abs(nx - hx!) + Math.abs(ny - hy!) < 8 || stairs.some(([sx, sy]) => Math.abs(nx - sx) + Math.abs(ny - sy) < 5));
