    const a = ultsOf(eq).find((u: { slot: EqKey; it: Item }) => isArmor(u.it.kind));
    if (w && fallbackW > now) out[w.slot] = clamp(fallbackW);
    if (a && fallbackA > now) out[a.slot] = clamp(fallbackA);
