  if (!IP.camOk || IP.camKey !== key || Math.hypot(tx - IP.camX, ty - IP.camY) > TS * 2.5) { IP.camX = tx; IP.camY = ty; IP.camOk = true; IP.camKey = key; }
  else { const k = Math.min(1, dt * 16); IP.camX += (tx - IP.camX) * k; IP.camY += (ty - IP.camY) * k; }
