  const gb = ctx.createLinearGradient(0, sy + 9, 0, sy + 22); gb.addColorStop(0, "#fff27a"); gb.addColorStop(0.5, "#ffc81e"); gb.addColorStop(1, "#d48a00");
  ctx.fillStyle = gb; ctx.fillRect(sx + 3, sy + 10, 18, 11);
