  if (!all.length) return false;
  const now = Date.now();
  const pick = slot
    ? all.find((u: { slot: EqKey; it: Item }) => u.slot === slot)
    : all.find((u: { slot: EqKey; it: Item }) => now >= ultCd(g, u.slot));
