  if (g.artCave && !g.artCave.open && g.artCave.dx === h.x + wantDx && g.artCave.dy === h.y + wantDy && artInside(g, h.x, h.y)) { h.bump = 0.6; h.bdx = wantDx; h.bdy = wantDy; openArtifactDoor(g); g.notify(); return; }
