  for (const p of allPassives(g.eq)) if (p.ty === "steps") { addGround(g, px, py, p.el, 3 + (p.mod === 4 ? 2 : 0), Math.max(1, Math.round(st.atk * p.pw * 0.6 * (p.mod === 3 ? 1.6 : 1)))); if (g.turn % 3 === 0) g.sfx("mx", pasSnd(p)); }
