    const NKU_MAX: Record<string, number> = { nkSkSmash: 3, nkSkClack: 2, nkGhostHit: 3, nkBone: 3, nkGrave: 2, nkSkRise: 2, nkSkGrowl: 1, nkPhalanx: 1 };
