          songI = ((i | 0) % SONGS.length + SONGS.length) % SONGS.length;
          songBar = 0; musStep = 0; inBoss = false; inCamp = false; bossNow = false; campNow = false; lastMusDepth = 1; musOn = false;
          let t = 0, n = 0, peak = 0;
